        <input
          id="couponCode"
          name="couponCode"
          value={code}
          onChange={(event) => setCode(event.target.value)}
          onKeyDown={handleKeyDown}
          autoComplete="off"
          placeholder="Ví dụ: SHOPLITE10"
          aria-invalid={Boolean(message)}
          aria-describedby={message ? MESSAGE_ID : undefined}
          className={cn(
